insert into kafaa_lectures (id, title_en, title_ar, abstract_en, abstract_ar, speaker_id, speaker_name, speaker_name_ar, speaker_role_id, format, lang, delivered_on, duration_min, recording_code, chapters, skill_ids, position_id, position_title_en, position_title_ar, system_family, status, published, published_by, published_at, withdrawn_reason, synthetic, history, created_by, created_at, updated_at) values
('lec-001', 'Digital I&C for maintainers: what changes after the analogue cards', 'أنظمة القياس والتحكم الرقمية لفنيي الصيانة: ما الذي يتغير بعد البطاقات التناظرية', 'A senior maintainer walks through how fault finding changes when protection and control move from analogue cards to digital platforms: self-diagnostics, configuration control, and why the electronic work package becomes the record of what was touched.', 'يشرح فني صيانة أول كيف يتغير تحديد الأعطال عندما تنتقل أنظمة الحماية والتحكم من البطاقات التناظرية إلى المنصات الرقمية: التشخيص الذاتي، وضبط التهيئة، ولماذا تصبح حزمة العمل الإلكترونية سجلاً لكل ما جرى العمل عليه.', 'w-mnt-01', 'Humaid Al Ketbi', 'حميد الكتبي', 'maintenance-technician-engineer', 'masterclass', 'en', '2026-05-14', 55, 'REC-2026-001', '[{"at":0,"en":"Why digital I&C changes the job","ar":"لماذا تغير الأنظمة الرقمية طبيعة العمل"},{"at":14,"en":"Self-diagnostics and what they do not tell you","ar":"التشخيص الذاتي وما لا يخبرك به"},{"at":31,"en":"Configuration control in practice","ar":"ضبط التهيئة عملياً"},{"at":46,"en":"The electronic work package as the record","ar":"حزمة العمل الإلكترونية بوصفها السجل"}]'::jsonb, array['sk-fs-dp-dic','sk-fs-dp-ework']::text[], 'pos-w-mnt-01', 'Mechanical, Electrical and I&C Maintenance Technician and Engineer', 'فني ومهندس صيانة ميكانيكية وكهربائية وأجهزة وتحكم', 'i_and_c', 'published', true, 'p-training-mgr', '2026-05-21T10:00:00Z', null, true, '[{"at":"2026-05-17T09:00:00Z","status":"review","by":"w-mnt-01","note":null},{"at":"2026-05-21T10:00:00Z","status":"published","by":"p-training-mgr","note":null}]'::jsonb, 'w-mnt-01', '2026-05-17T09:00:00Z', '2026-05-21T10:00:00Z'),
('lec-002', 'One control room, several modules: operating concepts explained', 'غرفة تحكم واحدة لعدة وحدات: شرح مفاهيم التشغيل', 'A shift supervisor compares crew work on a large unit with the multi-module operating concepts published for small modular reactors: shared displays, staffing questions and how shift turnover would need to change. Concepts only; no deployment decision is implied.', 'يقارن مشرف مناوبة عمل الطاقم في وحدة كبيرة بمفاهيم تشغيل الوحدات المتعددة المنشورة للمفاعلات المعيارية الصغيرة: الشاشات المشتركة، وأسئلة التوظيف، وكيف ينبغي أن يتغير تسليم المناوبة. مفاهيم فقط ولا يترتب على ذلك أي قرار بالنشر.', 'w-ss-01', 'Saeed Al Ketbi', 'سعيد الكتبي', 'shift-supervisor', 'talk', 'en', '2026-06-18', 40, 'REC-2026-002', '[{"at":0,"en":"Crew roles on a large unit today","ar":"أدوار الطاقم في الوحدة الكبيرة اليوم"},{"at":12,"en":"What multi-module operation means","ar":"ما المقصود بتشغيل الوحدات المتعددة"},{"at":25,"en":"Turnover and situational awareness","ar":"تسليم المناوبة والوعي بالموقف"}]'::jsonb, array['sk-fs-adv-multimodule']::text[], 'pos-w-ss-01', 'Shift Supervisor / Shift Manager · Crew A', 'مشرف / مدير الوردية · الطاقم A', 'reactor_core', 'published', true, 'p-training-mgr', '2026-06-25T10:00:00Z', null, true, '[{"at":"2026-06-21T09:00:00Z","status":"review","by":"w-ss-01","note":null},{"at":"2026-06-25T10:00:00Z","status":"published","by":"p-training-mgr","note":null}]'::jsonb, 'w-ss-01', '2026-06-21T09:00:00Z', '2026-06-25T10:00:00Z'),
('lec-003', 'Factory fabrication QA: inspecting a module before it ships', 'ضمان الجودة في التصنيع بالمصنع: فحص الوحدة قبل شحنها', 'How receiving inspection habits carry over when large components are built and tested in a factory: hold points at the supplier, witness inspections, and the documents a site team should expect to receive with a finished module.', 'كيف تنتقل عادات فحص الاستلام عندما تُصنع المكونات الكبيرة وتُختبر في المصنع: نقاط التوقف لدى المورد، وعمليات الفحص بالحضور، والوثائق التي ينبغي أن يتسلمها فريق الموقع مع الوحدة المكتملة.', 'w-qa-01', 'Majid Al Ketbi', 'ماجد الكتبي', 'quality-assurance-qc', 'walkthrough', 'en', '2026-07-09', 45, 'REC-2026-003', '[{"at":0,"en":"From receiving inspection to the factory floor","ar":"من فحص الاستلام إلى أرض المصنع"},{"at":15,"en":"Hold points and witness inspections","ar":"نقاط التوقف والفحص بالحضور"},{"at":32,"en":"What arrives with the module","ar":"ما يصل مع الوحدة"}]'::jsonb, array['sk-fs-adv-factoryqa']::text[], 'pos-w-qa-01', 'Quality Assurance / QC / NDE', 'ضمان الجودة / مراقبة الجودة / الفحص غير الإتلافي', 'maintenance', 'published', true, 'p-training-mgr', '2026-07-16T10:00:00Z', null, true, '[{"at":"2026-07-12T09:00:00Z","status":"review","by":"w-qa-01","note":null},{"at":"2026-07-16T10:00:00Z","status":"published","by":"p-training-mgr","note":null}]'::jsonb, 'w-qa-01', '2026-07-12T09:00:00Z', '2026-07-16T10:00:00Z'),
('lec-004', 'Waste stewardship and circularity in plant chemistry', 'الإشراف على النفايات والاقتصاد الدائري في كيمياء المحطة', 'A chemist explains how resin, filter and chemical use decisions shape the volume of waste the plant produces, and which small habits in the laboratory and on the systems reduce it over a fuel cycle.', 'تشرح كيميائية كيف تحدد قرارات استخدام الراتنجات والمرشحات والمواد الكيميائية حجم النفايات التي تنتجها المحطة، وما العادات الصغيرة في المختبر وعلى الأنظمة التي تقللها على مدى دورة الوقود.', 'w-chem-01', 'Sara Al Ketbi', 'سارة الكتبي', 'chemistry-technician', 'talk', 'ar', '2026-08-05', 35, 'REC-2026-004', '[{"at":0,"en":"Where chemistry waste comes from","ar":"من أين تأتي نفايات الكيمياء"},{"at":10,"en":"Resins and filters: choices that matter","ar":"الراتنجات والمرشحات: خيارات مؤثرة"},{"at":22,"en":"Habits that reduce volume","ar":"عادات تقلل الحجم"}]'::jsonb, array['sk-fs-gr-circular','sk-fs-tr-environment']::text[], 'pos-w-chem-01', 'Chemistry Technician / Chemist', 'فني كيمياء / كيميائي', 'chemistry', 'published', true, 'p-training-mgr', '2026-08-12T10:00:00Z', null, true, '[{"at":"2026-08-08T09:00:00Z","status":"review","by":"w-chem-01","note":null},{"at":"2026-08-12T10:00:00Z","status":"published","by":"p-training-mgr","note":null}]'::jsonb, 'w-chem-01', '2026-08-08T09:00:00Z', '2026-08-12T10:00:00Z'),
('lec-005', 'Robots and remote inspection during an outage', 'الروبوتات والفحص عن بعد خلال فترة الصيانة', 'An outage maintainer shares what changed when crawler and submersible tools took over some inspections: planning the deployment, keeping dose low, reviewing the video record and deciding when a person still needs to look.', 'يشارك فني صيانة كيف تغير العمل حين تولت أدوات الزحف والأدوات المغمورة بعض عمليات الفحص: تخطيط الاستخدام، وخفض الجرعة الإشعاعية، ومراجعة التسجيل المرئي، وتحديد متى ما زال على الإنسان أن ينظر بنفسه.', 'w-mnt-02', 'Sultan Al Mazrouei', 'سلطان المزروعي', 'maintenance-technician-engineer', 'walkthrough', 'en', '2026-08-27', 50, 'REC-2026-005', '[{"at":0,"en":"Which inspections moved to remote tools","ar":"أي عمليات الفحص انتقلت إلى الأدوات عن بعد"},{"at":13,"en":"Planning a deployment","ar":"تخطيط الاستخدام"},{"at":28,"en":"Reviewing the record","ar":"مراجعة التسجيل"},{"at":41,"en":"When a person still looks","ar":"متى ينظر الإنسان بنفسه"}]'::jsonb, array['sk-fs-dp-robotics']::text[], 'pos-w-mnt-02', 'Mechanical, Electrical and I&C Maintenance Technician and Engineer', 'فني ومهندس صيانة ميكانيكية وكهربائية وأجهزة وتحكم', 'outage', 'published', true, 'p-training-mgr', '2026-09-03T10:00:00Z', null, true, '[{"at":"2026-08-30T09:00:00Z","status":"review","by":"w-mnt-02","note":null},{"at":"2026-09-03T10:00:00Z","status":"published","by":"p-training-mgr","note":null}]'::jsonb, 'w-mnt-02', '2026-08-30T09:00:00Z', '2026-09-03T10:00:00Z'),
('lec-006', 'Grid integration and flexible operation: the plant engineer''s view', 'التكامل مع الشبكة والتشغيل المرن: منظور مهندس المحطة', 'Why grid operators ask nuclear plants about flexibility, what load following means for margins and equipment, and the engineering questions a utility studies before it changes how a unit is dispatched. Based on published studies; no ENEC operating plan is implied.', 'لماذا يسأل مشغلو الشبكات محطات الطاقة النووية عن المرونة، وما معنى متابعة الأحمال بالنسبة للهوامش والمعدات، والأسئلة الهندسية التي تدرسها شركة المرافق قبل تغيير طريقة تشغيل الوحدة. يستند إلى دراسات منشورة ولا يعني أي خطة تشغيل لدى المؤسسة.', 'p-sme-reviewer', 'SME reviewer (role card)', 'مراجع خبير (بطاقة دور)', 'systems-design-plant-engineer', 'masterclass', 'en', '2026-09-03', 60, 'REC-2026-006', '[{"at":0,"en":"What the grid needs from baseload plants","ar":"ما تحتاجه الشبكة من محطات الحمل الأساسي"},{"at":18,"en":"Load following and margins","ar":"متابعة الأحمال والهوامش"},{"at":37,"en":"Questions before changing dispatch","ar":"أسئلة قبل تغيير التشغيل"}]'::jsonb, array['sk-fs-gr-grid']::text[], 'pos-p-sme-reviewer', 'Systems, Design and Plant Engineer', 'مهندس أنظمة وتصميم ومحطة', 'electrical', 'published', true, 'p-training-mgr', '2026-09-10T10:00:00Z', null, true, '[{"at":"2026-09-06T09:00:00Z","status":"review","by":"p-sme-reviewer","note":null},{"at":"2026-09-10T10:00:00Z","status":"published","by":"p-training-mgr","note":null}]'::jsonb, 'p-sme-reviewer', '2026-09-06T09:00:00Z', '2026-09-10T10:00:00Z'),
('lec-007', 'Lifecycle carbon of a nuclear plant, from concrete to decommissioning', 'البصمة الكربونية لمحطة نووية على مدى عمرها من الخرسانة إلى الإيقاف النهائي', 'An engineer walks through how lifecycle assessments count emissions for a nuclear plant: construction materials, fuel supply, operation and decommissioning, and why the method matters when results are compared.', 'يشرح مهندس كيف تحسب تقييمات دورة الحياة الانبعاثات لمحطة نووية: مواد البناء وإمداد الوقود والتشغيل والإيقاف النهائي، ولماذا تهم المنهجية عند مقارنة النتائج.', 'w-eng-01', 'Khalid Al Suwaidi', 'خالد السويدي', 'systems-design-plant-engineer', 'talk', 'en', '2026-09-24', 45, 'REC-2026-007', '[{"at":0,"en":"What a lifecycle assessment counts","ar":"ما يحسبه تقييم دورة الحياة"},{"at":15,"en":"Construction and fuel supply","ar":"البناء وإمداد الوقود"},{"at":30,"en":"Comparing results fairly","ar":"مقارنة النتائج بإنصاف"}]'::jsonb, array['sk-fs-gr-lifecycle']::text[], 'pos-w-eng-01', 'Systems, Design and Plant Engineer', 'مهندس أنظمة وتصميم ومحطة', 'secondary', 'published', true, 'p-training-mgr', '2026-10-01T10:00:00Z', null, true, '[{"at":"2026-09-27T09:00:00Z","status":"review","by":"w-eng-01","note":null},{"at":"2026-10-01T10:00:00Z","status":"published","by":"p-training-mgr","note":null}]'::jsonb, 'w-eng-01', '2026-09-27T09:00:00Z', '2026-10-01T10:00:00Z'),
('lec-008', 'Keeping dose low: lessons from twenty outages', 'إبقاء الجرعة منخفضة: دروس من عشرين فترة صيانة', 'A radiation protection technician shares the planning habits that kept collective dose down across many outages: pre-job briefings, shielding decisions, time in the field and what to log so the next crew learns from it.', 'تشارك فنية الوقاية من الإشعاع عادات التخطيط التي أبقت الجرعة الجماعية منخفضة عبر فترات صيانة كثيرة: إحاطات ما قبل العمل، وقرارات التدريع، والوقت في الميدان، وما يجب تدوينه ليتعلم منه الطاقم التالي.', 'w-rp-02', 'Fatima Al Mazrouei', 'فاطمة المزروعي', 'radiation-protection-technician', 'talk', 'ar', '2026-09-29', 40, 'REC-2026-008', '[{"at":0,"en":"Planning before the job","ar":"التخطيط قبل العمل"},{"at":12,"en":"Shielding and time in the field","ar":"التدريع والوقت في الميدان"},{"at":27,"en":"What to log for the next crew","ar":"ما يجب تدوينه للطاقم التالي"}]'::jsonb, array['sk-rp-01','sk-fs-tr-environment']::text[], 'pos-w-rp-02', 'Radiation Protection Technician / Health Physicist / ALARA', 'فني وقاية من الإشعاع / فيزيائي صحي / أخصائي ALARA', 'radiation_protection', 'published', true, 'p-training-mgr', '2026-10-06T10:00:00Z', null, true, '[{"at":"2026-10-02T09:00:00Z","status":"review","by":"w-rp-02","note":null},{"at":"2026-10-06T10:00:00Z","status":"published","by":"p-training-mgr","note":null}]'::jsonb, 'w-rp-02', '2026-10-02T09:00:00Z', '2026-10-06T10:00:00Z'),
('lec-009', 'Shift turnover with digital rounds: what the log still needs', 'تسليم المناوبة مع الجولات الرقمية: ما الذي يحتاجه السجل', 'A senior reactor operator and colleagues discuss how handheld rounds change the turnover conversation: what the device records well, what it misses, and the questions an oncoming operator should still ask face to face.', 'يناقش مشغل مفاعل أول وزملاؤه كيف تغير الجولات المحمولة حوار تسليم المناوبة: ما يسجله الجهاز جيداً وما يفوته، والأسئلة التي ينبغي أن يطرحها المشغل القادم وجهاً لوجه.', 'w-sro-01', 'Nasser Al Marzooqi', 'ناصر المرزوقي', 'senior-reactor-operator', 'panel', 'en', '2026-10-01', 55, 'REC-2026-009', '[{"at":0,"en":"What digital rounds record","ar":"ما تسجله الجولات الرقمية"},{"at":16,"en":"What they miss","ar":"ما تفوته"},{"at":34,"en":"Questions to ask face to face","ar":"أسئلة تُطرح وجهاً لوجه"}]'::jsonb, array['sk-fs-dp-rounds','sk-co-01']::text[], 'pos-w-sro-01', 'Senior Reactor Operator (SRO), incl. unit supervisor · Crew B', 'مشغّل مفاعل أول (بما في ذلك مشرف الوحدة) · الطاقم B', 'human_performance', 'published', true, 'p-training-mgr', '2026-10-08T10:00:00Z', null, true, '[{"at":"2026-10-04T09:00:00Z","status":"review","by":"w-sro-01","note":null},{"at":"2026-10-08T10:00:00Z","status":"published","by":"p-training-mgr","note":null}]'::jsonb, 'w-sro-01', '2026-10-04T09:00:00Z', '2026-10-08T10:00:00Z'),
('lec-010', 'Advanced fuel cycles: what a specification engineer should know', 'دورات الوقود المتقدمة: ما ينبغي أن يعرفه مهندس المواصفات', 'An introduction to the fuel forms discussed for advanced reactors and what they would mean for procurement specifications and supplier qualification. Awareness level; no deployment decision is implied.', 'مقدمة عن أشكال الوقود المطروحة للمفاعلات المتقدمة وما قد تعنيه لمواصفات الشراء وتأهيل الموردين. على مستوى التوعية ولا يترتب على ذلك أي قرار بالنشر.', 'p-nse', 'Nuclear Specification Engineer (role card)', 'مهندس المواصفات النووية (بطاقة دور)', 'procurement-engineer', 'talk', 'en', '2026-09-16', 35, 'REC-2026-010', '[{"at":0,"en":"Fuel forms in the advanced-reactor literature","ar":"أشكال الوقود في أدبيات المفاعلات المتقدمة"},{"at":12,"en":"What changes in a specification","ar":"ما يتغير في المواصفات"},{"at":24,"en":"Supplier qualification questions","ar":"أسئلة تأهيل الموردين"}]'::jsonb, array['sk-fs-adv-fuelcycle']::text[], 'pos-p-nse', 'Procurement / Supply Chain / Nuclear Procurement Engineer', 'مهندس مشتريات / سلسلة إمداد / مشتريات نووية', 'reactor_core', 'published', true, 'p-training-mgr', '2026-09-23T10:00:00Z', null, true, '[{"at":"2026-09-19T09:00:00Z","status":"review","by":"p-nse","note":null},{"at":"2026-09-23T10:00:00Z","status":"published","by":"p-training-mgr","note":null}]'::jsonb, 'p-nse', '2026-09-19T09:00:00Z', '2026-09-23T10:00:00Z'),
('lec-011', 'Fire protection walkdowns: reading the plant', 'جولات الحماية من الحريق: قراءة المحطة', 'A fire protection specialist shows how to walk a building with fresh eyes: combustible loading, transient materials after maintenance, and the small signs that a fire barrier needs attention.', 'يوضح متخصص في الحماية من الحريق كيف يتجول في المبنى بعين جديدة: الأحمال القابلة للاشتعال، والمواد المؤقتة بعد الصيانة، والعلامات الصغيرة التي تدل على أن حاجز الحريق يحتاج إلى عناية.', 'w-fire-01', 'Omar Al Marzooqi', 'عمر المرزوقي', 'fire-protection', 'walkthrough', 'ar', '2026-09-15', 30, 'REC-2026-011', '[{"at":0,"en":"Walking with fresh eyes","ar":"التجول بعين جديدة"},{"at":9,"en":"Transient materials after maintenance","ar":"المواد المؤقتة بعد الصيانة"},{"at":19,"en":"Fire barriers that need attention","ar":"حواجز الحريق التي تحتاج إلى عناية"}]'::jsonb, array['sk-ep-02-fire']::text[], 'pos-w-fire-01', 'Fire Protection', 'الحماية من الحرائق', 'emergency_preparedness', 'published', true, 'p-training-mgr', '2026-09-22T10:00:00Z', null, true, '[{"at":"2026-09-18T09:00:00Z","status":"review","by":"w-fire-01","note":null},{"at":"2026-09-22T10:00:00Z","status":"published","by":"p-training-mgr","note":null}]'::jsonb, 'w-fire-01', '2026-09-18T09:00:00Z', '2026-09-22T10:00:00Z'),
('lec-012', 'Startup physics tests: notes from the core', 'اختبارات فيزياء بدء التشغيل: ملاحظات من القلب', 'A core physicist explains what the low-power physics tests confirm after refuelling, how the measured values are compared with predictions, and what the team does when a result sits near its acceptance band.', 'يشرح فيزيائي القلب ما تؤكده اختبارات الفيزياء عند القدرة المنخفضة بعد إعادة التزويد بالوقود، وكيف تقارن القيم المقيسة بالتوقعات، وما يفعله الفريق حين تقترب نتيجة من حدود القبول.', 'w-eng-05', 'Yousef Al Suwaidi', 'يوسف السويدي', 'reactor-engineer-core-physicist', 'talk', 'en', '2026-07-22', 50, 'REC-2026-012', '[{"at":0,"en":"Why the tests are run","ar":"لماذا تُجرى الاختبارات"},{"at":14,"en":"Measured against predicted","ar":"المقيس مقابل المتوقع"},{"at":33,"en":"Results near the band","ar":"نتائج قريبة من الحدود"}]'::jsonb, array['sk-pf-01-core']::text[], 'pos-w-eng-05', 'Reactor Engineer / Core Physicist', 'مهندس مفاعل / فيزيائي القلب', 'reactor_core', 'published', true, 'p-training-mgr', '2026-07-29T10:00:00Z', null, true, '[{"at":"2026-07-25T09:00:00Z","status":"review","by":"w-eng-05","note":null},{"at":"2026-07-29T10:00:00Z","status":"published","by":"p-training-mgr","note":null}]'::jsonb, 'w-eng-05', '2026-07-25T09:00:00Z', '2026-07-29T10:00:00Z'),
('lec-013', 'Designing a drill from the controller''s seat', 'تصميم تمرين الطوارئ من مقعد المتحكم', 'An emergency preparedness coordinator explains how a drill scenario is built so that it tests decisions rather than memory: objectives first, realistic timelines, and the evaluation points the controllers watch for.', 'يشرح منسق التأهب للطوارئ كيف يُبنى سيناريو التمرين بحيث يختبر القرارات لا الحفظ: الأهداف أولاً، والجداول الزمنية الواقعية، ونقاط التقييم التي يراقبها المتحكمون.', 'w-ep-01', 'Humaid Al Ketbi', 'حميد الكتبي', 'emergency-preparedness-coordinator', 'talk', 'en', '2026-09-30', 40, 'REC-2026-013', '[{"at":0,"en":"Objectives before the scenario","ar":"الأهداف قبل السيناريو"},{"at":13,"en":"Realistic timelines","ar":"جداول زمنية واقعية"},{"at":27,"en":"What controllers evaluate","ar":"ما يقيمه المتحكمون"}]'::jsonb, array['sk-ep-01']::text[], 'pos-w-ep-01', 'Emergency Preparedness Coordinator / ERO member', 'منسق التأهب للطوارئ / عضو منظمة الاستجابة للطوارئ', 'emergency_preparedness', 'review', false, null, null, null, true, '[{"at":"2026-10-03T09:00:00Z","status":"review","by":"w-ep-01","note":null}]'::jsonb, 'w-ep-01', '2026-10-03T09:00:00Z', '2026-10-03T10:00:00Z'),
('lec-014', 'Digital procurement and the receiving inspection', 'الشراء الرقمي وفحص الاستلام', 'A quality inspector shows how supplier documents arriving through a digital procurement portal change the receiving inspection: what can be checked before the item arrives and what must still be checked on the item itself.', 'يوضح مفتش جودة كيف تغير وثائق الموردين الواردة عبر بوابة الشراء الرقمية فحص الاستلام: ما يمكن التحقق منه قبل وصول القطعة وما يجب التحقق منه على القطعة نفسها.', 'p-qc-inspector', 'QC Receiving Inspector (role card)', 'مفتش جودة الاستلام (بطاقة دور)', 'quality-assurance-qc', 'walkthrough', 'en', '2026-10-05', 30, 'REC-2026-014', '[{"at":0,"en":"Documents before the item","ar":"الوثائق قبل القطعة"},{"at":11,"en":"Checks on the item itself","ar":"الفحوص على القطعة نفسها"}]'::jsonb, array['sk-fs-dp-procurement','sk-qa-01']::text[], 'pos-p-qc-inspector', 'Quality Assurance / QC / NDE', 'ضمان الجودة / مراقبة الجودة / الفحص غير الإتلافي', 'maintenance', 'review', false, null, null, null, true, '[{"at":"2026-10-08T09:00:00Z","status":"review","by":"p-qc-inspector","note":null}]'::jsonb, 'p-qc-inspector', '2026-10-08T09:00:00Z', '2026-10-08T10:00:00Z'),
('lec-015', 'Microreactors and transportable units: concepts for operators', 'المفاعلات الدقيقة والوحدات القابلة للنقل: مفاهيم للمشغلين', 'A shift supervisor''s draft notes on the operating concepts published for microreactors and transportable units, and the questions they raise for crew training. Concepts only; no deployment decision is implied.', 'مسودة ملاحظات مشرف مناوبة حول مفاهيم التشغيل المنشورة للمفاعلات الدقيقة والوحدات القابلة للنقل، والأسئلة التي تثيرها لتدريب الأطقم. مفاهيم فقط ولا يترتب على ذلك أي قرار بالنشر.', 'p-sro', 'Shift Manager · licensed SRO, Crew B (role card)', 'مدير الوردية · مشغّل أول مرخّص، الطاقم ب (بطاقة دور)', 'shift-supervisor', 'talk', 'en', '2026-09-21', 30, null, '[{"at":0,"en":"What a microreactor is","ar":"ما المفاعل الدقيق"},{"at":10,"en":"Questions for crew training","ar":"أسئلة لتدريب الأطقم"}]'::jsonb, array['sk-fs-adv-micro']::text[], 'pos-p-sro', 'Shift Supervisor / Shift Manager · Crew B', 'مشرف / مدير الوردية · الطاقم B', 'reactor_core', 'draft', false, null, null, null, true, '[{"at":"2026-09-24T09:00:00Z","status":"draft","by":"p-sro","note":null}]'::jsonb, 'p-sro', '2026-09-24T09:00:00Z', '2026-09-24T10:00:00Z'),
('lec-016', 'Answering stakeholder questions on nuclear and climate', 'الإجابة عن أسئلة أصحاب المصلحة حول الطاقة النووية والمناخ', 'A communications professional shares how to answer common questions about nuclear energy and climate with sourced facts, and when to refer a question to a subject matter expert.', 'تشارك مختصة في الاتصال كيفية الإجابة عن الأسئلة الشائعة حول الطاقة النووية والمناخ بحقائق موثقة، ومتى تُحال المسألة إلى خبير متخصص.', 'w-corp-01', 'Reem Al Ketbi', 'ريم الكتبي', 'corporate-professional', 'talk', 'en', '2026-06-25', 35, 'REC-2026-015', '[{"at":0,"en":"Common questions","ar":"أسئلة شائعة"},{"at":12,"en":"Answering with sourced facts","ar":"الإجابة بحقائق موثقة"},{"at":25,"en":"When to refer to an expert","ar":"متى تُحال المسألة إلى خبير"}]'::jsonb, array['sk-fs-gr-climaterisk']::text[], 'pos-w-corp-01', 'Corporate: HR, Finance, Legal, Communications, Stakeholder Engagement', 'الخدمات المؤسسية: الموارد البشرية والمالية والقانونية والاتصال وإشراك أصحاب المصلحة', 'training', 'withdrawn', false, 'p-training-mgr', '2026-07-02T10:00:00Z', 'An updated recording is planned', true, '[{"at":"2026-06-28T09:00:00Z","status":"review","by":"w-corp-01","note":null},{"at":"2026-07-02T10:00:00Z","status":"published","by":"p-training-mgr","note":null},{"at":"2026-07-07T10:00:00Z","status":"withdrawn","by":"w-corp-01","note":"An updated recording is planned"}]'::jsonb, 'w-corp-01', '2026-06-28T09:00:00Z', '2026-07-07T10:00:00Z'),
('lec-017', 'Records an independent reviewer can follow', 'سجلات يستطيع المراجع المستقل تتبّعها', 'What makes a work record easy to review months later: who did what, against which revision, with what result, and how electronic work packages help or hide that trail. Drawn from a reviewer''s side of the table.', 'ما الذي يجعل سجل العمل سهل المراجعة بعد أشهر: من قام بماذا، ووفق أي مراجعة، وبأي نتيجة، وكيف تساعد حزم العمل الإلكترونية في إظهار هذا الأثر أو تخفيه. من منظور المراجع.', 'p-presenter', 'Presenter (read-only walkthrough)', 'مقدّم العرض (قراءة فقط)', null, 'talk', 'en', '2026-09-09', 35, 'REC-2026-016', '[{"at":0,"en":"Who, what, which revision","ar":"من وماذا ووفق أي مراجعة"},{"at":12,"en":"Electronic packages: help or hide","ar":"الحزم الإلكترونية: تساعد أم تخفي"},{"at":24,"en":"Writing for the next reader","ar":"الكتابة للقارئ التالي"}]'::jsonb, array['sk-fs-tr-dependable','sk-fs-dp-ework']::text[], null, '', '', 'training', 'published', true, 'p-training-mgr', '2026-09-16T10:00:00Z', null, true, '[{"at":"2026-09-12T09:00:00Z","status":"review","by":"p-presenter","note":null},{"at":"2026-09-16T10:00:00Z","status":"published","by":"p-training-mgr","note":null}]'::jsonb, 'p-presenter', '2026-09-12T09:00:00Z', '2026-09-16T10:00:00Z')
